import { useState } from 'react';
import {
  JxInputField,
  JxSelect,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const roleOptions = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email);
  const showError = email.length > 0 && !isEmailValid;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isEmailValid) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm, 12px)' }}>
      {submitted && (
        <JxAlert
          intent="success"
          title="Приглашение отправлено"
          onClose={() => setSubmitted(false)}
        >
          Приглашение для {email} отправлено.
        </JxAlert>
      )}
      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          placeholder="name@example.com"
          required
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          helperText={showError ? undefined : 'Отправим приглашение на этот адрес'}
          errorText={showError ? 'Введите корректный адрес электронной почты' : undefined}
        />
        <JxSelect
          label="Роль"
          options={roleOptions}
          value={role}
          onValueChange={setRole}
        />
        <JxSwitch
          label="Отправить уведомление о приглашении"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />
        <div>
          <JxButton type="submit" variant="primary" disabled={!isEmailValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

